const { call } = require('../../../utils/api')
const { centToEuro, euroToCent } = require('../../../utils/format')
const { getSession } = require('../../../utils/session')

function clampImages(arr) {
  const out = Array.isArray(arr) ? arr.filter(Boolean) : []
  return out.slice(0, 10)
}

function chooseImages(remain) {
  // Return { tempFilePaths: string[], tempFiles?: [{tempFilePath}] }
  // Add a timeout so it never "does nothing" silently on buggy devices.
  const timeoutMs = 8000
  const timeout = new Promise((_, reject) => {
    setTimeout(() => reject(new Error('打开选择器超时，请重试')), timeoutMs)
  })

  const chooseMedia = () =>
    new Promise((resolve, reject) => {
      wx.chooseMedia({
        count: remain,
        mediaType: ['image'],
        sourceType: ['album', 'camera'],
        success: resolve,
        fail: reject,
      })
    })

  const chooseImage = () =>
    new Promise((resolve, reject) => {
      wx.chooseImage({
        count: remain,
        sizeType: ['compressed'],
        sourceType: ['album', 'camera'],
        success: resolve,
        fail: reject,
      })
    })

  const main = (async () => {
    // Prefer chooseMedia when available, but fallback if it fails on real devices.
    if (typeof wx.chooseMedia === 'function') {
      try {
        return await Promise.race([chooseMedia(), timeout])
      } catch (err) {
        const msg = (err && (err.errMsg || err.message)) || ''
        // Common: "api not supported" or other platform quirks.
        if (typeof wx.chooseImage === 'function') {
          return await Promise.race([chooseImage(), timeout])
        }
        throw new Error(msg || '选择图片失败')
      }
    }
    if (typeof wx.chooseImage === 'function') {
      return await Promise.race([chooseImage(), timeout])
    }
    throw new Error('当前微信版本不支持选择图片')
  })()

  return main
}

Page({
  data: {
    dishId: '',
    name: '',
    priceEuro: '',
    isActive: true,
    images: [], // fileIDs
    imageUrls: [], // temp urls for preview
    descMd: '',
    saving: false,
    uploading: false,
  },

  async onLoad(query) {
    const dishId = (query && query.dishId) || ''
    this.setData({ dishId })
    if (!dishId) return
    const res = await call('admin', 'getDish', { dishId })
    if (!res.ok) {
      wx.showToast({ title: res.message || '加载失败', icon: 'none' })
      return
    }
    const d = res.data.dish
    this.setData({
      name: d.name || '',
      priceEuro: centToEuro(d.priceFen || 0),
      isActive: !!d.isActive,
      images: clampImages(d.images || []),
      imageUrls: clampImages(d.imageUrls || d.images || []),
      descMd: d.descMd || '',
    })
  },

  onName(e) {
    this.setData({ name: e.detail.value })
  },

  onPrice(e) {
    this.setData({ priceEuro: e.detail.value })
  },

  onActive(e) {
    this.setData({ isActive: !!e.detail.value })
  },

  onDesc(e) {
    this.setData({ descMd: e.detail.value })
  },

  async addImages() {
    if (!wx.cloud) {
      wx.showToast({ title: '请先启用云开发', icon: 'none' })
      return
    }
    if (this.data.uploading) return
    if ((this.data.images || []).length >= 10) {
      wx.showToast({ title: '最多 10 张', icon: 'none' })
      return
    }
    const remain = 10 - (this.data.images || []).length
    // Quick feedback so user knows the tap is handled.
    try {
      wx.vibrateShort({ type: 'light' })
    } catch (e) {
      // ignore
    }
    wx.showToast({ title: '打开相册/相机...', icon: 'none', duration: 800 })

    let chooseRes = null
    try {
      chooseRes = await chooseImages(remain)
    } catch (err) {
      const msg = (err && (err.errMsg || err.message)) || ''
      if (msg && msg.includes('cancel')) return
      wx.showToast({ title: msg || '选择图片失败', icon: 'none' })
      return
    }

    const files = (chooseRes.tempFiles || []).map((f) => f.tempFilePath).filter(Boolean)
    if (files.length === 0 && Array.isArray(chooseRes.tempFilePaths)) {
      files.push(...chooseRes.tempFilePaths.filter(Boolean))
    }
    if (files.length === 0) return

    this.setData({ uploading: true })
    wx.showLoading({ title: '上传中...' })
    try {
      const sess = await getSession()
      const openId = sess.openId || 'anon'
      const ts = Date.now()
      const uploaded = []
      for (let i = 0; i < files.length; i++) {
        const filePath = files[i]
        const cloudPath = `dish-images/${openId}/${ts}-${i}.jpg`
        const up = await wx.cloud.uploadFile({ cloudPath, filePath })
        uploaded.push(up.fileID)
      }
      const images = clampImages([...(this.data.images || []), ...uploaded])
      const urlRes = await wx.cloud.getTempFileURL({ fileList: uploaded })
      const urlMap = new Map((urlRes.fileList || []).map((x) => [x.fileID, x.tempFileURL]))
      const uploadedUrls = uploaded.map((id) => urlMap.get(id) || '')
      const imageUrls = clampImages([...(this.data.imageUrls || []), ...uploadedUrls])
      this.setData({ images, imageUrls })
    } catch (err) {
      wx.showToast({ title: (err && err.errMsg) || '上传失败', icon: 'none' })
    } finally {
      wx.hideLoading()
      this.setData({ uploading: false })
    }
  },

  removeImg(e) {
    const i = Number(e.currentTarget.dataset.i)
    const images = [...(this.data.images || [])]
    const imageUrls = [...(this.data.imageUrls || [])]
    images.splice(i, 1)
    imageUrls.splice(i, 1)
    this.setData({ images, imageUrls })
  },

  moveUp(e) {
    const i = Number(e.currentTarget.dataset.i)
    if (i <= 0) return
    const images = [...(this.data.images || [])]
    const imageUrls = [...(this.data.imageUrls || [])]
    ;[images[i - 1], images[i]] = [images[i], images[i - 1]]
    ;[imageUrls[i - 1], imageUrls[i]] = [imageUrls[i], imageUrls[i - 1]]
    this.setData({ images, imageUrls })
  },

  moveDown(e) {
    const i = Number(e.currentTarget.dataset.i)
    const images = [...(this.data.images || [])]
    const imageUrls = [...(this.data.imageUrls || [])]
    if (i < 0 || i >= images.length - 1) return
    ;[images[i + 1], images[i]] = [images[i], images[i + 1]]
    ;[imageUrls[i + 1], imageUrls[i]] = [imageUrls[i], imageUrls[i + 1]]
    this.setData({ images, imageUrls })
  },

  async save() {
    const name = String(this.data.name || '').trim()
    const priceFen = euroToCent(this.data.priceEuro)
    if (!name) {
      wx.showToast({ title: '请填写名称', icon: 'none' })
      return
    }
    if (priceFen <= 0) {
      wx.showToast({ title: '请填写价格', icon: 'none' })
      return
    }
    this.setData({ saving: true })
    const res = await call('admin', 'upsertDish', {
      dishId: this.data.dishId || null,
      name,
      priceFen,
      isActive: !!this.data.isActive,
      images: clampImages(this.data.images || []),
      descMd: String(this.data.descMd || ''),
    })
    this.setData({ saving: false })
    if (!res.ok) {
      wx.showToast({ title: res.message || '保存失败', icon: 'none' })
      return
    }
    wx.showToast({ title: '已保存', icon: 'success' })
    wx.navigateBack()
  },
})

