      if (!dish) continue
      const qty = Number(it.qty || 0)
      if (qty <= 0) continue
      const unitPriceCents = Number(dish.priceCents || 0)
      const lineTotalCents = unitPriceCents * qty
      totalCents += lineTotalCents
      lines.push({
        dishId: it.dishId,
        name: dish.name,
