    const saleData = saleRes.ok && saleRes.data ? saleRes.data : { sale: null, dishes: [] }
    const sale = saleData.sale
    const saleDishMap = new Map()
    for (const d of (saleData.dishes || [])) {
      if (!d || !d._id) continue
      saleDishMap.set(d._id, d)
    }
    const dishes = (browseRes.data && browseRes.data.dishes ? browseRes.data.dishes : []).map((d) => {
      const sd = saleDishMap.get(d._id) || null
      return {
