function normalizeDishConfigs(input) {
  if (!Array.isArray(input)) return []
  const seen = new Set()
  const out = []
  for (const raw of input) {
    const dishId = String((raw && raw.dishId) || '').trim()
    if (!dishId || seen.has(dishId)) continue
