    const picked = idx >= 0 ? arr[idx] : null
    this.setData({
      selectedAddressIndex: idx >= 0 ? idx : 0,
      selectedAddressTitle: picked ? picked.title : '',
      selectedAddressDetail: picked ? picked.detail : '',
    })
