const { call } = require('../../../utils/api')
const { centToEuro, euroToCent } = require('../../../utils/format')

function normalizeRows(input) {
  const arr = Array.isArray(input) ? input : []
  return arr.map((x) => ({
    city: String((x && x.city) || '').trim(),
    minEuro: String((x && x.minEuro) || '').trim(),
  }))
}

function uniqueCityList(input) {
  const arr = Array.isArray(input) ? input : []
  const out = []
  const seen = new Set()
  for (const s of arr) {
    const city = String((s && s.city) || '').trim()
    const key = city.toLowerCase().replace(/\s+/g, ' ')
    if (!city || seen.has(key)) continue
    seen.add(key)
    out.push(city)
  }
  return out
}

Page({
  data: {
    rows: [],
    defaultMinEuro: '',
    saving: false,
    loading: false,
    citySuggestIndex: -1,
    citySuggestions: [],
  },

  onShow() {
    this.reload()
  },

  onUnload() {
    if (this._citySuggestTimer) clearTimeout(this._citySuggestTimer)
  },

  async reload() {
    this.setData({ loading: true })
    const res = await call('admin', 'getDeliveryRules')
    this.setData({ loading: false })
    if (!res.ok) {
      wx.showToast({ title: res.message || '加载失败', icon: 'none' })
      return
    }
    const raw = (res.data && res.data.deliveryMinByCity) || {}
    const rows = Object.keys(raw)
      .map((city) => ({ city, minEuro: centToEuro(raw[city]) }))
      .sort((a, b) => a.city.localeCompare(b.city))
    const defaultMinEuro = centToEuro((res.data && res.data.deliveryMinDefaultCents) || 0)
    this.setData({
      rows,
      defaultMinEuro: defaultMinEuro === '0.00' ? '' : defaultMinEuro,
      citySuggestIndex: -1,
      citySuggestions: [],
    })
  },

  onCityInput(e) {
    const idx = Number(e.currentTarget.dataset.idx)
    const val = String((e.detail && e.detail.value) || '')
    const rows = normalizeRows(this.data.rows)
    if (!rows[idx]) return
    rows[idx].city = val.trim()
    this.setData({ rows })
    this.debouncedSuggestCity(idx, val)
  },

  onCityFocus(e) {
    const idx = Number(e.currentTarget.dataset.idx)
    const rows = normalizeRows(this.data.rows)
    const row = rows[idx]
    if (!row) return
    this.debouncedSuggestCity(idx, row.city)
  },

  onCityBlur() {
    setTimeout(() => {
      this.setData({ citySuggestIndex: -1, citySuggestions: [] })
    }, 120)
  },

  debouncedSuggestCity(idx, q) {
    const s = String(q || '').trim()
    if (this._citySuggestTimer) clearTimeout(this._citySuggestTimer)
    if (s.length < 2) {
      this.setData({ citySuggestIndex: -1, citySuggestions: [] })
      return
    }
    this._citySuggestTimer = setTimeout(() => {
      this.fetchCitySuggestions(idx, s)
    }, 220)
  },

  async fetchCitySuggestions(idx, q) {
    const rows = normalizeRows(this.data.rows)
    if (!rows[idx]) return
    const res = await call('customer', 'suggestAddress', { q, limit: 8 })
    if (!res.ok) {
